import sys
from decimal import Decimal


def main():
    data = sys.stdin.buffer.read()
    sums = {}
    get = sums.get
    for line in data.split(b"\n")[1:]:
        _, sep, rest = line.partition(b",")
        cat, sep2, v = rest.partition(b",")
        if not sep2:
            continue
        v = v.strip()
        if v.isdigit():
            cents = int(v) * 100
        else:
            cents = None
            if b"." in v and v[:1] != b"-" and v[:1] != b"+":
                ip, fp = v.split(b".", 1)
                if len(fp) == 2 and fp.isdigit() and (ip.isdigit() or ip == b""):
                    cents = int(ip or b"0") * 100 + int(fp)
            if cents is None:
                if not v:
                    continue
                cents = int((Decimal(v.decode()) * 100).to_integral_value())
        sums[cat] = get(cat, 0) + cents
    out = []
    for cat in sorted(sums):
        c = sums[cat]
        sign = "-" if c < 0 else ""
        c = abs(c)
        out.append("%s,%s%d.%02d" % (cat.decode(), sign, c // 100, c % 100))
    sys.stdout.write("\n".join(out) + ("\n" if out else ""))


main()
